def completar_renovaciones_viejas(apps, schema_editor):
    """Las renovaciones anteriores no guardaban cómo estaba el consultorio: se asume el día previo y el mismo plan."""
    Suscripcion = apps.get_model('plataforma', 'Suscripcion')
    for s in Suscripcion.objects.all():
        s.hasta_anterior = s.desde - timedelta(days=1)
        s.plan_anterior_id = s.plan_id
        s.save(update_fields=['hasta_anterior', 'plan_anterior'])


